/* Original reference algorithm; matching Python implementation in disaster_response/. */
export const defaults={pressure:1,horizon_minutes:60,risk_limit:.72,congestion:1,shelter_scale:1,closed_roads:[],closed_shelters:[],accessible_only:true,max_age_minutes:120};
const rounded=x=>Math.round(x);
class Flow{
 constructor(){this.graph=new Map();this.forward=[];}
 add(u,v,cap,cost=0,meta=null){if(!this.graph.has(u))this.graph.set(u,[]);if(!this.graph.has(v))this.graph.set(v,[]);let a={u,v,cap,initial:cap,cost,rev:this.graph.get(v).length,meta},b={u:v,v:u,cap:0,initial:0,cost:-cost,rev:this.graph.get(u).length,meta:null};this.graph.get(u).push(a);this.graph.get(v).push(b);this.forward.push(a);return a;}
 solve(src,dst){let total=0;while(true){let dist=new Map([...this.graph.keys()].map(k=>[k,Infinity])),prev=new Map();dist.set(src,0);for(let i=0;i<this.graph.size-1;i++){let changed=false;for(let [u,edges] of this.graph){if(!Number.isFinite(dist.get(u)))continue;for(let e of edges)if(e.cap>0&&dist.get(e.v)>dist.get(u)+e.cost){dist.set(e.v,dist.get(u)+e.cost);prev.set(e.v,e);changed=true;}}if(!changed)break;}if(!prev.has(dst))break;let path=[],v=dst;while(v!==src){let e=prev.get(v);path.push(e);v=e.u;}let amount=Math.min(...path.map(e=>e.cap));for(let e of path){e.cap-=amount;this.graph.get(e.v)[e.rev].cap+=amount;}total+=amount;}return total;}
 paths(src,dst){let remaining=new Map(this.forward.map(e=>[e,e.initial-e.cap])),outgoing=new Map(),results=[];for(let e of this.forward){if(!outgoing.has(e.u))outgoing.set(e.u,[]);outgoing.get(e.u).push(e);}while(true){let q=[src],seen=new Set([src]),prev=new Map();for(let i=0;i<q.length&&!seen.has(dst);i++)for(let e of outgoing.get(q[i])||[])if(remaining.get(e)>0&&!seen.has(e.v)){seen.add(e.v);prev.set(e.v,e);q.push(e.v);}if(!seen.has(dst))break;let path=[],v=dst;while(v!==src){let e=prev.get(v);path.push(e);v=e.u;}path.reverse();let amount=Math.min(...path.map(e=>remaining.get(e)));for(let e of path)remaining.set(e,remaining.get(e)-amount);results.push([amount,path]);}return results;}
}
const fresh=(item,data,p)=>{let age=(Date.parse(data.as_of)-Date.parse(item.observed_at))/60000;return age>=0&&age<=p.max_age_minutes;};
export function roadState(r,d,p){if(p.closed_roads.includes(r.id)||r.status==='closed')return 'closed';if(r.status!=='verified_exercise')return 'unverified';if(!fresh(r,d,p))return 'stale';if(r.risk*p.pressure>=p.risk_limit)return 'hazard_excluded';return 'available_exercise';}
export function shortest(data,p,start,end){let dist=new Map(data.nodes.map(n=>[n.id,Infinity])),prev=new Map();dist.set(start,0);let available=data.roads.filter(r=>roadState(r,data,p)==='available_exercise');for(let i=0;i<dist.size-1;i++){let changed=false;for(let r of available)for(let [a,b] of [[r.u,r.v],...(r.oneway?[]:[[r.v,r.u]])])if(dist.get(b)>dist.get(a)+r.minutes*p.congestion){dist.set(b,dist.get(a)+r.minutes*p.congestion);prev.set(b,[a,r.id]);changed=true;}if(!changed)break;}if(!Number.isFinite(dist.get(end)))return null;let roads=[],v=end;while(v!==start){let [node,rid]=prev.get(v);v=node;roads.push(rid);}return {minutes:rounded(dist.get(end)*100)/100,roads:roads.reverse()};}
function dispatch(data,p){let f=new Flow(),src='__dispatch_source',dst='__dispatch_sink';f.graph.set(src,[]);f.graph.set(dst,[]);for(let r of data.resources)if(r.available&&r.status==='verified_exercise'&&fresh(r,data,p)){f.add(src,'asset:'+r.id,1);for(let c of data.communities){if(!c.needs[r.type])continue;let route=shortest(data,p,r.node,c.node);if(route&&route.minutes<=p.horizon_minutes)f.add('asset:'+r.id,'need:'+c.id+':'+r.type,1,rounded(route.minutes*10)-rounded(c.priority_score*100000),{asset:r.id,community:c.id,type:r.type,...route});}}for(let c of data.communities)for(let [kind,count] of Object.entries(c.needs))f.add('need:'+c.id+':'+kind,dst,count);f.solve(src,dst);let assignments=f.forward.filter(e=>e.meta&&e.initial>e.cap).map(e=>e.meta);return {assignments,requested_units:data.communities.reduce((a,c)=>a+Object.values(c.needs).reduce((s,x)=>s+x,0),0),assigned_units:assignments.length,scope:'Independent one-way first-wave arrivals; no seats, return trips, service times or shared road usage with evacuation flow.'};}
export function plan(data,options={}){if(data.mode!=='synthetic_exercise')throw Error('Only synthetic_exercise is supported');let p={...defaults,...options};for(let k of ['pressure','horizon_minutes','risk_limit','congestion','shelter_scale','max_age_minutes'])if(!Number.isFinite(p[k]))throw Error('Invalid '+k);if(p.pressure<0||p.pressure>3||p.horizon_minutes<1||p.horizon_minutes>240||p.risk_limit<=0||p.risk_limit>1||p.congestion<1||p.congestion>4||p.shelter_scale<0||p.shelter_scale>2||p.max_age_minutes<0||p.max_age_minutes>1440)throw Error('Scenario options outside supported bounds');let total=data.communities.reduce((s,c)=>s+c.population,0),f=new Flow(),src='__source',dst='__sink';f.graph.set(src,[]);f.graph.set(dst,[]);let available=[],excluded=[];for(let r of data.roads){let state=roadState(r,data,p);if(state==='available_exercise')available.push(r);else excluded.push({id:r.id,reason:state});}let weights=Object.fromEntries(available.map(r=>[r.id,rounded(r.minutes*p.congestion*10)+rounded(r.risk*p.pressure*100)])),bonus=(Object.values(weights).reduce((s,x)=>s+x,0)+1)*(total+1),supply=[];for(let c of data.communities)for(let [count,priority] of [[c.priority_population,true],[c.population-c.priority_population,false]])supply.push(f.add(src,c.node,count,priority?-bonus:0,{origin:c.id,priority}));let roadEdges=new Map();for(let r of available){let a='road_in:'+r.id,b='road_out:'+r.id;f.add(r.u,a,total);f.add(b,r.v,total);if(!r.oneway){f.add(r.v,a,total);f.add(b,r.u,total);}roadEdges.set(r.id,f.add(a,b,Math.floor(r.capacity_per_hour*p.horizon_minutes/60),weights[r.id],{road:r.id}));}let shelterEdges=new Map(),capacities={},unavailable=[];for(let s of data.shelters){let reason=null;if(p.closed_shelters.includes(s.id)||s.status!=='open_exercise')reason='closed_or_unverified';else if(!fresh(s,data,p))reason='stale';else if(p.accessible_only&&!s.accessible)reason='accessibility_filter';let cap=reason?0:Math.max(0,Math.floor(s.capacity*p.shelter_scale)-s.occupied);capacities[s.id]=cap;if(reason)unavailable.push({id:s.id,reason});shelterEdges.set(s.id,f.add(s.node,dst,cap,0,{shelter:s.id}));}let served=f.solve(src,dst),lookup=Object.fromEntries(data.roads.map(r=>[r.id,r]));let routes=f.paths(src,dst).map(([people,path])=>{let metas=path.filter(e=>e.meta).map(e=>e.meta),origin=metas.find(m=>m.origin),shelter=metas.find(m=>m.shelter).shelter,roads=metas.filter(m=>m.road).map(m=>m.road);return {community:origin.origin,shelter,priority:origin.priority,people,roads,minutes:rounded(roads.reduce((s,r)=>s+lookup[r].minutes,0)*p.congestion*100)/100};});let communities=data.communities.map(c=>{let own=supply.filter(e=>e.meta.origin===c.id),assigned=own.reduce((s,e)=>s+e.initial-e.cap,0),priority_served=own.filter(e=>e.meta.priority).reduce((s,e)=>s+e.initial-e.cap,0);return {id:c.id,population:c.population,assigned,unassigned:c.population-assigned,priority_served,priority_unassigned:c.priority_population-priority_served};});return {model_version:'0.1.0',mode:data.mode,as_of:data.as_of,options:p,objective:'maximize total assigned, then priority assigned, then minimize assumed travel+risk cost',total_demand:total,assigned:served,unassigned:total-served,priority_assigned:communities.reduce((s,c)=>s+c.priority_served,0),routes,communities,shelters:data.shelters.map(s=>({id:s.id,available_capacity:capacities[s.id],assigned:shelterEdges.get(s.id).initial-shelterEdges.get(s.id).cap})),road_usage:[...roadEdges].map(([id,e])=>({id,people:e.initial-e.cap,capacity:e.initial})),excluded_roads:excluded,excluded_shelters:unavailable,dispatch:dispatch(data,p),limitations:['Synthetic schematic graph, populations and shelters; not real navigation.','Static throughput flow; not a time-expanded evacuation clearance model.','Priority people are an aggregate planning group, not medical triage.','Resource dispatch is independent; evacuation seats and assistance are not guaranteed.','Travel minutes exclude queues, boarding, service and return trips.']};}
export function simulate(data,options={},runs=100,seed=42){let state=seed>>>0;const rand=()=>{state^=state<<13;state^=state>>>17;state^=state<<5;return (state>>>0)/4294967296;};const normal=()=>Math.sqrt(-2*Math.log(Math.max(1e-10,rand())))*Math.cos(2*Math.PI*rand());const poisson=lambda=>{if(lambda<30){let k=0,p=1,L=Math.exp(-lambda);do{k++;p*=rand();}while(p>L);return k-1;} // exact decomposition avoids normal approximation
 let result=0;while(lambda>20){let k=0,p=1,L=Math.exp(-20);do{k++;p*=rand();}while(p>L);result+=k-1;lambda-=20;}let k=0,p=1,L=Math.exp(-lambda);do{k++;p*=rand();}while(p>L);return result+k-1;};let P=[[.82,.16,.02],[.18,.63,.19],[.05,.25,.70]],samples=[],counts=[0,0,0];for(let i=0;i<runs;i++){let s=1;for(let t=0;t<3;t++){let u=rand(),c=0;for(let j=0;j<3;j++){c+=P[s][j];if(u<c){s=j;break;}}}counts[s]++;let d=structuredClone(data),shock=rand();for(let r of d.roads)if(r.risk>.3&&shock<[.01,.15,.45][s])r.status='closed';let factor=Math.exp(-.5*.12**2+.12*normal());for(let c of d.communities){let ratio=c.priority_population/Math.max(1,c.population);c.population=poisson(c.population*factor);c.priority_population=Math.min(c.population,rounded(c.population*ratio));}samples.push(plan(d,{...options,pressure:Math.min(3,(options.pressure??1)*[.8,1.05,1.4][s])}).unassigned);}let sorted=[...samples].sort((a,b)=>a-b),quant=q=>{let pos=(sorted.length-1)*q,lo=Math.floor(pos),hi=Math.ceil(pos);return sorted[lo]+(sorted[hi]-sorted[lo])*(pos-lo);};return {mode:'synthetic_assumptions',engine:'browser xorshift32 (different PRNG from Python)',seed,runs,steps_hours:3,transition_matrix:P,unassigned_samples:samples,unassigned_p50:quant(.5),unassigned_p95:quant(.95),probability_any_unassigned:samples.filter(x=>x>0).length/runs,state_counts:counts};}
